/**
 * Embedded notification sounds: mono 22.05kHz MP3 (64kbps), base64-encoded so
 * the client bundle carries the audio inline (client plugin bundles have no
 * static-file route; every non-JS asset must ride the JS bundle).
 *
 * Source of record: the original stereo WAVs under `assets/` (1.wav, 2.wav,
 * 3.wav). Regenerate all three with ffmpeg, then rewrite this file:
 *
 *   for i in 1 2 3; do
 *     ffmpeg -y -i assets/$i.wav -ac 1 -ar 22050 -c:a libmp3lame -b:a 64k /tmp/notify-$i.mp3
 *   done
 *   # then re-encode each /tmp/notify-$i.mp3 to base64 into the map below.
 *
 * Played through HTMLAudioElement with a data:audio/mpeg URL — supported by
 * every modern browser, no codec detection needed.
 */

/** One embedded sound keyed by the settings `sound` field. */
export type NotifySoundKey = keyof typeof NOTIFY_AUDIO

/** Base64 MP3 payload per selectable sound (see header for regeneration). */
export const NOTIFY_AUDIO = {
  a: '',
  b: '',
  c: '',
} as const
